INSERT INTO dashboard_templates (key, name, description, category, definition, created_at, updated_at)
VALUES ('traceway-clickhouse', 'Traceway ClickHouse', 'ClickHouse health of a monitored Traceway instance', 'traceway', '{"schemaVersion":1,"widgets":[{"title":"Inserted Rows","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.inserted_rows.delta","aggregation":"sum"}]}},{"title":"Failed Inserts","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.failed_inserts.delta","aggregation":"sum"}]}},{"title":"Delayed Inserts","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.delayed_inserts.delta","aggregation":"sum"}]}},{"title":"Rejected Inserts","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.rejected_inserts.delta","aggregation":"sum"}]}},{"title":"Active Parts","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.parts.active","aggregation":"avg"}]}},{"title":"Running Merges","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.merges.running","aggregation":"avg"}]}},{"title":"Memory","widgetType":"area_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.memory.tracking_bytes","aggregation":"avg"}]}},{"title":"Disk Used %","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.ch.disk.used_pcnt","aggregation":"avg"}]}}]}', datetime('now'), datetime('now'))
ON CONFLICT (key) DO NOTHING;
